import{_ as t}from"./chunks/dashboard-docker-error.CtiVSRfK.js";import{_ as o,o as n,c as r,a2 as a}from"./chunks/framework.Dhf_H6O0.js";const g=JSON.parse('{"title":"Docker Desktop","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/docker.md","filePath":"getting-started/docker.md"}'),i={name:"getting-started/docker.md"};function s(l,e,c,d,h,p){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="docker-desktop" tabindex="-1">Docker Desktop <a class="header-anchor" href="#docker-desktop" aria-label="Permalink to &quot;Docker Desktop&quot;">​</a></h1><p>MCPBehindIT runs the MCP gateway inside a Docker container. You need Docker Desktop installed and running on your Mac. The good news: <strong>MCPBehindIT handles this for you</strong>.</p><h2 id="automatic-setup" tabindex="-1">Automatic setup <a class="header-anchor" href="#automatic-setup" aria-label="Permalink to &quot;Automatic setup&quot;">​</a></h2><p>When you first open MCPBehindIT, it checks if Docker Desktop is available. There are three possible outcomes:</p><h3 id="docker-is-running" tabindex="-1">Docker is running <a class="header-anchor" href="#docker-is-running" aria-label="Permalink to &quot;Docker is running&quot;">​</a></h3><p>Nothing to do. You&#39;ll see a green <strong>Docker Reachable</strong> indicator on the Dashboard. Move on to <a href="./activate-license.html">activating your license</a>.</p><h3 id="docker-is-installed-but-not-running" tabindex="-1">Docker is installed but not running <a class="header-anchor" href="#docker-is-installed-but-not-running" aria-label="Permalink to &quot;Docker is installed but not running&quot;">​</a></h3><p>MCPBehindIT detects that Docker Desktop is on your machine but isn&#39;t started. It <strong>automatically launches Docker Desktop</strong> for you and waits until it&#39;s ready. You&#39;ll see a progress indicator while this happens.</p><p>No action needed — just wait a few seconds.</p><h3 id="docker-is-not-installed" tabindex="-1">Docker is not installed <a class="header-anchor" href="#docker-is-not-installed" aria-label="Permalink to &quot;Docker is not installed&quot;">​</a></h3><p>MCPBehindIT detects that Docker Desktop is missing and shows an <strong>Install Docker Desktop</strong> button.</p><p><img src="'+t+'" alt="Dashboard showing Docker unavailable error"></p><p>Click the button and MCPBehindIT will:</p><ol><li><strong>Download</strong> Docker Desktop (~700 MB). A progress bar shows the download status.</li><li><strong>Install</strong> it to your Applications folder.</li><li><strong>Start</strong> Docker Desktop.</li><li><strong>Wait</strong> until the Docker engine is ready.</li></ol><p>The entire process takes a few minutes depending on your internet speed. You don&#39;t need to do anything — just wait for the progress bar to complete.</p><div class="tip custom-block"><p class="custom-block-title">Manual alternative</p><p>If you prefer to install Docker Desktop yourself, click the <strong>&quot;Download manually from docker.com&quot;</strong> link and follow the instructions on the Docker website. Choose the version for your Mac:</p><ul><li><strong>Apple Silicon</strong> (M1/M2/M3/M4): <code>Docker Desktop for Mac with Apple Silicon</code></li><li><strong>Intel</strong>: <code>Docker Desktop for Mac with Intel chip</code></li></ul><p>After installing, open Docker Desktop once so it can finish its initial setup, then return to MCPBehindIT and click <strong>Re-check</strong>.</p></div><h2 id="verifying-docker-is-working" tabindex="-1">Verifying Docker is working <a class="header-anchor" href="#verifying-docker-is-working" aria-label="Permalink to &quot;Verifying Docker is working&quot;">​</a></h2><p>On the MCPBehindIT Dashboard, look at the <strong>phase strip</strong> at the top:</p><ul><li><strong>DOCKER</strong> should show <strong>Reachable</strong> with a green dot.</li><li>If it shows a red dot, click <strong>Re-check</strong> or restart Docker Desktop.</li></ul><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Docker is ready. Let&#39;s <a href="./activate-license.html">activate your license</a>.</p>',21)])])}const D=o(i,[["render",s]]);export{g as __pageData,D as default};
